_FONTS = {}


def _has_font(prefix):
    if prefix not in _FONTS:
        ok = False
        try:
            import winreg
            with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts") as k:
                i = 0
                while not ok:
                    ok = winreg.EnumValue(k, i)[0].startswith(prefix)
                    i += 1
        except (OSError, IndexError):
            pass
        _FONTS[prefix] = ok
    return _FONTS[prefix]


def apply_theme(db):
    global FONT_FAMILY, FONT_DISPLAY, R, PAD
    T.clear()
    theme = THEMES.get(db.get("theme"), THEMES["Obsidian"])
    T.update(theme)
    acc = db.get("accent")
    if re.fullmatch(r"#[0-9a-fA-F]{6}", acc or ""):
        T["accent"] = acc
    T["accent2"] = theme.get("accent2") or blend("#ffffff", T["accent"], .28)
    T["lav"] = theme.get("lav") or blend("#ffffff", T["accent"], .58)
    T["ok"], T["warn"], T["bad"] = OK, WARN, BAD
    T["hover"] = blend("#ffffff", T["panel2"], .08)
    T["glow"] = blend(T["accent"], T["bg"], .18)
    T["line"] = blend(T["text"], T["border"], .10)
    # 2026 surfaces: a little more depth than flat cards, and a violet-tinted edge for
    # interactive elements. Everything is derived from the active theme, so light themes
    # and custom accents keep working.
    T["panel3"] = blend("#ffffff", T["panel"], .045)
    T["elev"] = blend("#ffffff", T["panel2"], .055)
    T["edge"] = blend(T["accent"], T["border"], .44)
    T["accent_dark"] = blend("#000000", T["accent"], .28)
    T["accent_soft"] = blend(T["accent"], T["panel"], .13)
    T["accent_faint"] = blend(T["accent"], T["panel"], .055)
    T["grid"] = blend(T["text"], T["panel2"], .075)
    T["shadow"] = blend("#000000", T["bg"], .35)
    T["ok_soft"] = blend(OK, T["panel"], .13)
    T["warn_soft"] = blend(WARN, T["panel"], .13)
    T["bad_soft"] = blend(BAD, T["panel"], .13)
    R = db.num("radius", 0, 24)
    PAD = 8 if db.get("density") == "Compact" else 12
    fam = db.get("font") or "Segoe UI"
    if fam == "Segoe UI" and _has_font("Segoe UI Variable"):
        fam = "Segoe UI Variable Text"  # the Windows 11 / 2026 system font
    FONT_FAMILY = fam
    FONT_DISPLAY = fam
    if fam == "Segoe UI Variable Text" and _has_font("Segoe UI Variable Display"):
        FONT_DISPLAY = "Segoe UI Variable Display"
    ctk.set_appearance_mode(T["mode"])
    ctk.set_default_color_theme("dark-blue")


def F(size, bold=False):
    family = FONT_DISPLAY if int(size) >= 20 else FONT_FAMILY
    return ctk.CTkFont(family=family, size=int(size), weight="bold" if bold else "normal")


def ease_out(t):
    t = max(0.0, min(1.0, t))
    return 1 - (1 - t) ** 3


