    col = color or T["accent"]
    return ctk.CTkLabel(parent, text=(name[:1] or "?").upper(), width=size, height=size, corner_radius=size // 2,
                        fg_color=blend(col, T["panel"], .2), text_color=col, font=F(size * 0.42, True))


