    def close_all(self):
        if self.core.snapshot() and confirm(self.app, "Close every client?",
                                            "All Roblox windows launched by RoManager will be closed. "
                                            "Your accounts and saved sessions stay untouched.", danger=True):
            self.core.close_all()

    def save_layout(self):
        n = prompt(self.app, "Save layout", "Give this window arrangement a short name.", placeholder="e.g. Farm setup")
        if n and n.strip():
            self.core.save_layout(n.strip())
            self.app.toast(f"Layout '{n.strip()}' saved", "ok")

    def restore_layout(self):
        names = [r[0] for r in self.core.db.all("SELECT name FROM layouts ORDER BY name")]
        if not names:
            alert(self.app, "No saved layouts", "Arrange your windows, then use Save layout to store a setup.", "info")
            return
        n = prompt(self.app, "Load layout", "Saved layouts: " + ", ".join(names), placeholder=names[0])
        if n:
            try:
                self.core.restore_layout(n.strip())
            except ValueError as e:
                alert(self.app, "Layout not found", str(e), "bad")

    def resize(self, pid):
        s = prompt(self.app, "Resize window", "Enter WIDTHxHEIGHT. Any positive size works in Multi-View.",
                   placeholder="e.g. 320x180")
        wh = parse_wh(s)
        if wh:
            self.core.resize(pid, *wh)
        elif s:
            alert(self.app, "Invalid size", "Use the format WIDTHxHEIGHT, for example 320x180.", "bad")

    def make_card(self, c):
        row = self.core.db.one("SELECT color FROM accounts WHERE id=?", (c["account_id"],))
        col = (row[0] if row and row[0] else None) or T["accent"]
        f = card(self.list)
        ctk.CTkFrame(f, width=4, fg_color=col, corner_radius=0).place(x=0, y=14, relheight=0.84)
        body = ctk.CTkFrame(f, fg_color="transparent")
        body.pack(fill="both", expand=True, padx=(18, 14), pady=PAD)
        head = ctk.CTkFrame(body, fg_color="transparent")
        head.pack(fill="x")
        av = make_avatar(head, self.app, c["account_id"], c["name"], 42, col)
        av.pack(side="left")
        mid = ctk.CTkFrame(head, fg_color="transparent")
        mid.pack(side="left", padx=10)
        L(mid, c["name"], 15, True).pack(anchor="w")
        game = L(mid, "", 11, muted=True)
        game.pack(anchor="w")
        pl = pill(head, "Running", OK)
        pl.pack(side="right")
        bars = {}
        if self.core.db.flag("show_bars"):
            meter = ctk.CTkFrame(body, fg_color="transparent")
            meter.pack(fill="x", pady=(6, 0))
            for k, name in (("cpu", "CPU"), ("ram", "RAM"), ("gpu", "GPU")):
                r = ctk.CTkFrame(meter, fg_color="transparent")
                r.pack(fill="x", pady=1)
                L(r, name, 9, True, muted=True, width=30, anchor="w").pack(side="left")
                pb = ctk.CTkProgressBar(r, height=5, progress_color=T["accent"], fg_color=T["panel2"],
                                        corner_radius=3)
                pb.set(0)
                pb.pack(side="left", fill="x", expand=True, padx=7)
                vl = L(r, "", 9, width=86, anchor="e")
                vl.pack(side="left")
                bars[k] = (pb, vl)
        meta = L(body, "", 9, muted=True, anchor="w")
        meta.pack(fill="x", pady=(7, 6))
        row2 = ctk.CTkFrame(body, fg_color="transparent")
        row2.pack(fill="x")
        pid = c["pid"]
        for t, cmd, k in [("Focus", lambda: self.core.window_cmd(pid, "focus"), "ghost"),
                          ("Min", lambda: self.core.window_cmd(pid, "min"), "flat"),
                          ("Max", lambda: self.core.window_cmd(pid, "max"), "flat"),
                          ("Restore", lambda: self.core.window_cmd(pid, "restore"), "flat"),
                          ("Size", lambda: self.resize(pid), "flat"),
                          ("Restart", lambda: self.core.restart_client(pid), "flat"),
                          ("Close", lambda: self.core.close_client(pid), "danger")]:
            btn(row2, t, cmd, k, h=27).pack(side="left", padx=(0, 4))
        for w in (f, av, mid):
            w.bind("<Button-1>", lambda e, p=pid: self.core.window_cmd(p, "focus"))
        return {"frame": f, "game": game, "pill": pl, "bars": bars, "meta": meta, "av": av, "avimg": None}

    def regrid(self, order):
        cols = 2 if self.core.db.get("cols") == "2" else 1
        for i in range(2):
            self.list.grid_columnconfigure(i, weight=1 if i < cols else 0)
        for i, pid in enumerate(order):
            self.cards[pid]["frame"].grid(row=i // cols, column=i % cols, sticky="ew", padx=5, pady=5)

    def refresh(self):
        cl = sorted(self.core.snapshot(), key=lambda c: c["start"])
        alive = {c["pid"] for c in cl}
        for pid in list(self.cards):
            if pid not in alive:
                self.cards.pop(pid)["frame"].destroy()
        for c in cl:
            if c["pid"] not in self.cards:
                self.cards[c["pid"]] = self.make_card(c)
        order = [c["pid"] for c in cl]
        if order != self.order:
            self.order = order
            self.regrid(order)
        if cl:
            self.empty.grid_remove()
        else:
            self.empty.grid(row=0, column=0, columnspan=2, sticky="ew", padx=5, pady=16)
        for c in cl:
            k = self.cards[c["pid"]]
            state = win_state(c["hwnd"])
            if c["hung"] >= 1 or state == "Not responding":
                txt, col = "Not responding", BAD
            elif state == "Minimized":
                txt, col = "Minimized", WARN
            elif state == "No window":
                txt, col = "Starting", T["muted"]
            else:
                txt, col = "Running", OK
            k["pill"].configure(text=f"  {txt}  ", text_color=col, fg_color=blend(col, T["panel"], .14))
            k["game"].configure(text=f"{dest_label(c['dest'])}")
            capn = f"   ·   CPU cap {int(c['cap_now'])}%" if c.get("cap_now") else ""
            k["meta"].configure(text=f"PID {c['pid']}   ·   up {fmt_dur(time.time() - c['start'])}   ·   {state.lower()}{capn}")
            if "cpu" in k["bars"]:
                k["bars"]["cpu"][0].set(min(1, c["cpu"] * 4 / 100))
                k["bars"]["cpu"][1].configure(text=f"{c['cpu']:.1f}%")
                k["bars"]["ram"][0].set(min(1, c["rss"] / ((self.core.profile()["ramcap"] << 20) or 3e9)))
                k["bars"]["ram"][1].configure(text=fmt_mb(c["rss"]))
                g = c.get("gpu")
                k["bars"]["gpu"][0].set(min(1, (g or 0) * 4 / 100))
                k["bars"]["gpu"][1].configure(text="n/a" if g is None else f"{g:.1f}%")
            img = self.app.avatar(c["account_id"]) if self.core.db.flag("show_avatars") else None
            if img and k["avimg"] is not img:
                k["avimg"] = img
                k["av"].configure(image=img, text="", fg_color="transparent")
        h = list(self.core.hist)[-90:]
        tot_ram = sum(c["rss"] for c in cl)
        vals = {"clients": (str(len(cl)), "", [x["count"] for x in h]),
                "ram": (fmt_mb(tot_ram), "", [x["rb_ram"] for x in h]),
                "cpu": (f"{sum(c['cpu'] for c in cl):.1f}%", "", [x["rb_cpu"] for x in h]),
                "running": (str(len({c['account_id'] for c in cl})), "", None),
                "failed": (str(self.core.failed), "", None)}
        for key, (v, sub, data) in vals.items():
            self.stat[key][0].configure(text=v)
            if self.stat[key][2] is not None and data:
                self.stat[key][2].draw(data)
        try:
            n = len(cl)
            total = self.core.db.one("SELECT COUNT(*) FROM accounts")[0]
            self._hero_total = total
            ns = len(self.app.selected)
            running = len({c["account_id"] for c in cl})
            self.client_count.configure(text=str(n))
            self.stat["clients"][1].configure(
                text="live clients" + self._trend([x["count"] for x in h[-45:]], lambda d: f"{d:.0f}"))
            self.stat["ram"][1].configure(
                text="working set" + self._trend([x["rb_ram"] / 1048576 for x in h[-45:]],
                                                  lambda d: f"{d:.0f} MB"))
            self.stat["cpu"][1].configure(
                text="all clients" + self._trend([x["rb_cpu"] for x in h[-45:]], lambda d: f"{d:.1f}%"))
            self.stat["running"][1].configure(text=f"of {total} accounts")
            self.stat["failed"][1].configure(
                text="session clean" if self.core.failed == 0 else "open the log to inspect",
                text_color=T["muted"] if self.core.failed == 0 else BAD)
            try:
                self.runbar.set(running / total if total else 0)
                self.failnote.configure(text="no failures" if self.core.failed == 0 else "attention needed",
                                        text_color=T["muted"] if self.core.failed == 0 else BAD)
            except Exception:
                pass
            self.hero_live.configure(text=f"{n} client{'s' if n != 1 else ''} online"
                                           f"   ·   {sum(c['cpu'] for c in cl):.1f}% CPU")
            self.hero_ready.configure(text=f"{ns} selected  ·  {total} accounts")
            self.hero_multi.configure(text="ACTIVE" if self.core.mutex else "STANDBY",
                                      text_color=OK if self.core.mutex else WARN)
            self.hero_acc.configure(text=f"  {total} ACCOUNTS  ")
            self.hero_sel.configure(text=f"  {ns} SELECTED  ",
                                    text_color=T["accent"] if ns else T["muted"],
                                    fg_color=blend(T["accent"], T["panel"], .14) if ns else T["panel2"])
            self.hero_multi_pill.configure(
                text="  MULTI-INSTANCE ACTIVE  " if self.core.mutex else "  MULTI-INSTANCE OFF  ",
                text_color=OK if self.core.mutex else WARN,
                fg_color=blend(OK if self.core.mutex else WARN, T["panel"], .14))
            score = 55 + (30 if self.core.mutex else 0) + (15 if self._installed else 0)
            score -= min(55, self.core.failed * 9)
            if cl:
                score += 5
            score = max(8, min(100, score))
            self.gauge.set(score)
            if score >= 90:
                self.hero_health.configure(text="ALL SYSTEMS NOMINAL", text_color=OK)
            elif score >= 65:
                self.hero_health.configure(text="READY WITH WARNINGS", text_color=WARN)
            else:
                self.hero_health.configure(text="ATTENTION NEEDED", text_color=BAD)
            self.feed_dot.configure(text_color=OK if self.core.logs else T["muted"])
            self._refresh_activity()
        except Exception:
            pass

    @staticmethod
    def _trend(data, fmt):
        if len(data) < 4:
            return ""
        d = data[-1] - data[0]
        if abs(d) < 1e-9:
            return "  ·  steady"
        return f"  ·  {'▲' if d > 0 else '▼'} {fmt(abs(d))}"

    def _refresh_activity(self):
        if self._feed_total == self.core.log_total:
            return
        self._feed_total = self.core.log_total
        for w in self.feed.winfo_children():
            w.destroy()
        logs = list(self.core.logs)[-8:]
        if not logs:
            L(self.feed, "No activity yet. Launch a client and the live feed appears here.",
              10, muted=True, justify="left", wraplength=226).pack(anchor="w", padx=10, pady=14)
            return
        for line in reversed(logs):
            low = line.lower()
            if any(k in low for k in ("error", "failed", "could not", "cannot", "gave up")):
                col = BAD
            elif any(k in low for k in ("started", "active", "ready", "saved", "added", "signed", "complete")):
                col = OK
            elif any(k in low for k in ("warn", "skip", "pause", "standby")):
                col = WARN
            else:
                col = T["accent"]
            row = ctk.CTkFrame(self.feed, fg_color="transparent")
            row.pack(fill="x", padx=3, pady=3)
            L(row, "●", 7, color=col).pack(side="left", anchor="n", padx=(3, 7), pady=(3, 0))
            L(row, line, 10, muted=True, justify="left", wraplength=222, anchor="w").pack(
                side="left", fill="x", expand=True, pady=1)


