    def copy_diag(self):
        try:
            db = self.core.db
            acc = db.one("SELECT COUNT(*) FROM accounts")[0]
            groups = db.one("SELECT COUNT(*) FROM groups")[0]
            cl = self.core.snapshot()
            lines = [
                APP_NAME + " diagnostics",
                f"Version: 2.6 / 2026 edition",
                f"Windows: {sys.getwindowsversion().major}.{sys.getwindowsversion().minor}",
                f"Python: {sys.version.split()[0]}",
                f"Theme: {db.get('theme')}  ·  scale {db.get('ui_scale')}%  ·  density {db.get('density')}",
                f"Accounts: {acc}  ·  groups: {groups}  ·  selected: {len(self.app.selected)}",
                f"Clients: {len(cl)}  ·  multi-instance: {'active' if self.core.mutex else 'off'}",
                f"Uptime: {fmt_dur(time.time() - self.core.started)}",
                f"Data folder: {APPDIR}",
            ]
            self.app.clipboard_clear()
            self.app.clipboard_append("\n".join(lines))
            self.app.toast("Diagnostics copied to the clipboard", "ok")
        except Exception as e:
            self.app.toast(f"Could not copy diagnostics: {e}", "bad")

    def refresh(self):
        try:
            acc = self.core.db.one("SELECT COUNT(*) FROM accounts")[0]
            cl = self.core.snapshot()
            self.about_acc.configure(text=f"{acc} accounts")
            self.about_cli.configure(text=f"{len(cl)} live clients", text_color=OK if cl else T["muted"])
            self.about_up.configure(text="up " + fmt_dur(time.time() - self.core.started))
        except Exception:
            pass

    def pick_accent(self):
        c = colorchooser.askcolor(parent=self.app)[1]
        if c:
            self.accent["v"] = c

    def apply_appearance(self):
        db = self.core.db
        db.set("theme", self.v["theme"].get())
        db.set("accent", self.accent["v"])
        db.set("ui_scale", int(self.v["scale"].get()))
        db.set("radius", int(self.v["radius"].get()))
        db.set("opacity", int(self.v["opacity"].get()))
        db.set("density", self.v["density"].get())
        db.set("cols", self.v["cols"].get())
        db.set("font", self.v["font"].get())
        for k, s in self.sw.items():
            db.set(k, "1" if s.get() else "0")
        self.app.after(30, lambda: self.app.rebuild("Settings"))

    def autostart(self):
        import winreg
        try:
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion\Run", 0, winreg.KEY_SET_VALUE) as k:
                if self.core.db.flag("autostart"):
                    cmd = (f'"{sys.executable}" --autostart' if getattr(sys, "frozen", False)
                           else f'"{sys.executable}" "{os.path.abspath(sys.argv[0])}" --autostart')
                    winreg.SetValueEx(k, APP_NAME, 0, winreg.REG_SZ, cmd)
                else:
                    try:
                        winreg.DeleteValue(k, APP_NAME)
                    except FileNotFoundError:
                        pass
        except OSError as e:
            alert(self.app, "Startup setting", f"Could not change startup setting: {e}", "bad")

    def save_wh(self):
        url = self.wh.get().strip()
        if not WEBHOOK_RE.match(url):
            self.whmsg.configure(text="Not a valid Discord webhook URL.", text_color=BAD)
            return
        self.whmsg.configure(text="Sending test message…", text_color=T["muted"])

        def done(ok, err):
            if ok:
                self.core.db.set("webhook", dpapi_protect(url.encode()).hex())
                self.wh.delete(0, "end")
                self.whmsg.configure(text="Webhook saved (test message sent).", text_color=OK)
            else:
                self.whmsg.configure(text="Discord rejected the test message. Not saved.", text_color=BAD)

        self.app.bg(lambda: discord_post(url, "RoManager webhook test."), done)

    def rm_wh(self):
        self.core.db.set("webhook", "")
        self.whmsg.configure(text="Webhook removed.", text_color=T["muted"])

    def set_pw(self):
        a = ask_secret(self.app, "Master password", "New master password:")
        if not a:
            return
        if len(a) < 6:
            alert(self.app, "Password too short", "Use at least 6 characters.", "warn")
            return
        if ask_secret(self.app, "Master password", "Repeat it:") != a:
            alert(self.app, "Passwords did not match", "The two entries were not identical. Nothing was changed.", "bad")
            return
        self.core.db.set("lock_hash", hash_pw(a))
        alert(self.app, "Master password set", "RoManager will ask for it every time it starts.", "ok")

    def rm_pw(self):
        h = self.core.db.get("lock_hash")
        if h and verify_pw(ask_secret(self.app, "Master password", "Current password:") or "", h):
            self.core.db.set("lock_hash", "")
        elif h:
            alert(self.app, "Wrong password", "The master password was not changed.", "bad")


