class Splash:
    """A lightweight, always-visible start-up card drawn with plain Tk (immune to CTk scaling rebuilds)."""

    W, H = 508, 316
    TOTAL = 6.6  # the splash stays up for at least this many seconds

    def __init__(self, app):
        self._born = time.time()
        self._value = 0.0
        self._stage = ""
        self.top = tk.Toplevel(app)
        self.top.overrideredirect(True)
        sw, sh = self.top.winfo_screenwidth(), self.top.winfo_screenheight()
        x, y = (sw - self.W) // 2, (sh - self.H) // 2
        self.top.geometry(f"{self.W}x{self.H}+{x}+{y}")
        self.top.attributes("-topmost", True)
        self.top.configure(bg="#09090D")
        c = tk.Canvas(self.top, width=self.W, height=self.H, bg="#09090D", highlightthickness=0)
        c.pack(fill="both", expand=True)
        for i in range(self.H):
            t = i / max(1, self.H - 1)
            r = int(18 * (1 - t) + 9 * t)
            g = int(10 * (1 - t) + 9 * t)
            b = int(30 * (1 - t) + 13 * t)
            c.create_line(0, i, self.W, i, fill=f"#{r:02x}{g:02x}{b:02x}")
        # soft ultraviolet halo behind the mark
        for r in (82, 68, 54):
            c.create_oval(self.W // 2 - r, 28 - r // 2, self.W // 2 + r, 28 + r, outline="", fill=blend("#A855F7", "#0E0A16", .06))
        self.pulse = c.create_oval(0, 0, 0, 0, outline=blend(T["accent"], "#0E0A16", .30), width=1)
        c.create_rectangle(self.W // 2 - 27, 28, self.W // 2 + 27, 82, fill=T["accent"], outline="")
        c.create_text(self.W // 2, 55, text="◆", fill="#FFFFFF", font=(FONT_DISPLAY, 27, "bold"))
        c.create_text(self.W // 2, 108, text="RoManager", fill=T["text"], font=(FONT_DISPLAY, 26, "bold"))
        c.create_text(self.W // 2, 132, text="R O B L O X   M U L T I - A C C O U N T   S U I T E",
                      fill=T["muted"], font=(FONT_FAMILY, 8, "bold"))
        c.create_rectangle(self.W // 2 - 46, 150, self.W // 2 + 46, 172, fill=blend(T["accent"], "#0E0A16", .16),
                           outline="")
        c.create_text(self.W // 2, 161, text="2 0 2 6   E D I T I O N", fill=T["lav"], font=(FONT_FAMILY, 8, "bold"))
        c.create_rectangle(self.W // 2 - 176, 224, self.W // 2 + 176, 230, fill="#241B31", outline="")
        self.prog = c.create_rectangle(self.W // 2 - 176, 224, self.W // 2 - 176, 230, fill=T["accent"], outline="")
        self.phead = c.create_rectangle(self.W // 2 - 176, 223, self.W // 2 - 176, 231,
                                        fill=blend("#FFFFFF", T["accent"], .35), outline="")
        self.orbits = []
        for col, rad in ((T["lav"], 0), (blend(T["accent"], "#FFFFFF", .3), 180)):
            self.orbits.append((c.create_oval(0, 0, 0, 0, fill=col, outline=""), rad))
        self.status = c.create_text(self.W // 2, 258, text="Starting…", fill=T["muted"], font=(FONT_FAMILY, 10))
        self.pct = c.create_text(self.W // 2 + 176, 240, text="0%", anchor="e",
                                 fill=blend(T["muted"], "#09090D", .30), font=(FONT_FAMILY, 8, "bold"))
        c.create_text(self.W // 2, 292, text="WINDOWS 10 / 11   ·   ULTRAVIOLET EDITION",
                      fill=blend(T["muted"], "#09090D", .45), font=(FONT_FAMILY, 7, "bold"))
        self.canvas = c
        self._alive = True
        self.top.update()
        self._animate(0)

    def _animate(self, n):
        if not self._alive:
            return
        try:
            phase = (n % 70) / 70
            r = 34 + 38 * phase
            x, y = self.W // 2, 55
            self.canvas.coords(self.pulse, x - r, y - r, x + r, y + r)
            self.canvas.itemconfigure(self.pulse, outline=blend(T["accent"], "#0E0A16", .34 * (1 - phase)))
            for item, off in self.orbits:
                a = math.radians(n * 3.4 + off)
                ox, oy = x + math.cos(a) * 46, y + math.sin(a) * 30
                self.canvas.coords(item, ox - 2.3, oy - 2.3, ox + 2.3, oy + 2.3)
            self.canvas.itemconfigure(self.status, fill=blend(T["muted"], T["lav"], .5 + .5 * math.sin(n / 9)))
            self.top.after(44, lambda: self._animate(n + 1))
        except Exception:
            pass

    def step(self, text, value):
        try:
            v = max(0.0, min(1.0, value))
            self._value = v
            self._stage = text
            self.canvas.itemconfigure(self.status, text=text)
            x = self.W // 2 - 176 + int(352 * v)
            self.canvas.coords(self.prog, self.W // 2 - 176, 224, x, 230)
            self.canvas.coords(self.phead, max(self.W // 2 - 176, x - 3), 223, x + 3, 231)
            self.top.update()
        except Exception:
            pass

    def finish(self, app, total=None):
        """Ease to 100% over the remaining time, pumping both event loops so motion stays live."""
        total = self.TOTAL if total is None else max(1.0, total)
        stages = (
            (0.00, "Preparing the interface…"),
            (0.18, "Loading your accounts…"),
            (0.42, "Waking the fleet…"),
            (0.66, "Restoring your workspace…"),
            (0.86, "Almost there…"),
            (0.995, "Ready"),
        )
        start_v = max(0.0, min(0.99, self._value))
        end_at = self._born + total
        start_at = time.time()
        span = max(0.12, end_at - start_at)
        stage_i, last_pct = 0, -1
        try:
            app.update()
        except Exception:
            pass
        while self._alive:
            remain = end_at - time.time()
            if remain <= 0:
                break
            frac = min(1.0, max(0.0, 1 - remain / span))
            value = start_v + (1 - start_v) * (1 - (1 - frac) ** 1.7)
            for idx, (threshold, _text) in enumerate(stages):
                if value >= threshold:
                    stage_i = idx
            self.step(stages[stage_i][1], min(0.998, value))
            pct = int(round(min(99.0, value * 100)))
            if pct != last_pct:
                last_pct = pct
                try:
                    self.canvas.itemconfigure(self.pct, text=f"{pct}%")
                except Exception:
                    pass
            try:
                app.update()
                self.top.update()
            except Exception:
                break
            time.sleep(0.016)
        self.step("Ready", 1.0)
        try:
            self.canvas.itemconfigure(self.pct, text="100%")
        except Exception:
            pass
        hold = time.time() + 0.5
        while self._alive and time.time() < hold:
            try:
                app.update()
                self.top.update()
            except Exception:
                break
            time.sleep(0.016)
        self.close()

    def close(self):
        self._alive = False
        try:
            for i in range(10):
                self.top.attributes("-alpha", 1 - i / 10)
                self.top.update()
                time.sleep(0.012)
            self.top.destroy()
        except Exception:
            pass


class LazyPages(dict):
    """Builds a tab the first time it is opened, so start-up and idle memory stay small."""

    def __init__(self, app, classes):
        super().__init__()
        self.app, self.classes = app, classes

    def __missing__(self, name):
        page = self.classes[name](self.app.content, self.app)
        self[name] = page
        return page


class App(ctk.CTk):
    NAV = [
        ("Home", "Dashboard", "▦", "WORKSPACE"),
        ("Accounts", "Accounts", "☺", "WORKSPACE"),
        ("Play", "Play", "▶", "WORKSPACE"),
        ("Windows", "Windows", "▣", "CONTROL"),
        ("MultiView", "Multi-View", "▤", "CONTROL"),
        ("Monitor", "Monitor", "◔", "CONTROL"),
        ("Performance", "Performance", "⚡", "CONTROL"),
        ("Settings", "Settings", "⚙", "SYSTEM"),
    ]

    def __init__(self, core):
        super().__init__()
        self._closing = False
        self._visibility_tries = 0
        self.attributes("-alpha", 0.0)
        self.core = core
        self.selected, self.avatars, self.uiq, self.toasts = set(), {}, queue.Queue(), []
        self.current = "Home"
        self._pop = None
        self._palette = None
        self._pal_sel = 0
        self._pal_rows = []
        self._pal_items = []
        self._navbadge = {}
        self._side_spark = None
        self._loadveil = None
        self._loadfill = None
        self._loadspin = None
        self._loadseq = 0
        self._pending_page = None
        self._nav_target = "Home"
        self._page_ready = None
        self.seen_log = core.log_total
        self.title(APP_NAME)
        self.geometry("1360x860")
        self.minsize(1120, 700)
        self.protocol("WM_DELETE_WINDOW", self.on_close)
        apply_theme(core.db)
        self.configure(fg_color=T["bg"])
        threading.Thread(target=self._startup_watchdog, daemon=True).start()
        splash = Splash(self)
        splash.step("Preparing the interface…", 0.08)
        self.build()
        splash.step("Loading your accounts…", 0.18)
        self.show("Home", veil=False)
        style_window(self)
        splash.step("Waking the fleet…", 0.28)
        self.update_idletasks()
        splash.finish(self)
        start_min = core.db.flag("start_min") and "--autostart" in sys.argv
        if start_min:
            self.iconify()
            self.attributes("-alpha", 1.0)
            READY.set()
        else:
            self.deiconify()
            self.attributes("-alpha", 0.0)
            if core.db.flag("anim"):
                self.fade(0)
            else:
                self.attributes("-alpha", min(1.0, core.db.num("opacity", 50, 100) / 100))
            self.bring_to_front()
        self.after(90, self.pump)
        self.after(1000, self.tick)
        self.after(160, self._verify_visible)
        self.after(2600, self._startup_toasts)
        self.bind_all("<Control-k>", self.open_palette)
        self.bind_all("<Control-f>", self._focus_search)
        self.bind_all("<Control-b>", lambda e: self.toggle_sidebar())
        self.bind_all("<F5>", lambda e: self.refresh_current())
        self.bind_all("<Escape>", self._escape)
        for i in range(8):
            self.bind_all(f"<Control-Key-{i + 1}>", lambda e, k=self.NAV[i][0]: self.show(k))

    # -- start-up / visibility
    def _startup_watchdog(self):
        if READY.wait(45):
            return
        try:
            import traceback
            lines = []
            for tid, frame in list(sys._current_frames().items()):
                lines.append(f"--- thread {tid} ---\n" + "".join(traceback.format_stack(frame)[-8:]))
            _log_crash("STARTUP WATCHDOG: the main window was not visible after 45 seconds.\n\n" + "\n".join(lines))
        except Exception:
            pass
        try:
            user32.MessageBoxW(0, "RoManager is taking much longer than expected to show its window.\n\n"
                                   "A diagnostic report was written to crash.log in %APPDATA%\\RoManager.\n"
                                   "Close this message and wait a moment, or end RoManager from Task Manager.",
                                APP_NAME, 0x30)
        except Exception:
            pass

    def _verify_visible(self):
        if self._closing:
            return
        try:
            if not self.core.db.flag("start_min") or "--autostart" not in sys.argv:
                self.deiconify()
                target = min(1.0, self.core.db.num("opacity", 50, 100) / 100)
                if float(self.attributes("-alpha") or 0) < target - .02:
                    self.attributes("-alpha", target)
                self.lift()
            READY.set()
        except Exception:
            pass
        self._visibility_tries += 1
        if self._visibility_tries < 2:
            self.after(2500, self._verify_visible)

    def _startup_toasts(self):
        try:
            if not self.core.mutex:
                self.toast(self.core.multi_status, "warn")
            if not roblox_installed():
                self.toast("Roblox Player not found for this Windows user. Install it from roblox.com.", "warn")
        except Exception:
            pass

    def _focus_search(self, _=None):
        try:
            self.gq.focus_set()
            self.gq.select_range(0, "end")
        except Exception:
            pass

    def _escape(self, _=None):
        if self._palette is not None:
            self.close_palette()
            return "break"
        if self._pop is not None:
            self._close_pop()
            return "break"

    def refresh_current(self):
        try:
            self.pages[self.current].refresh()
        except Exception as e:
            self.core.log(f"UI error: {e}")

    def cycle_theme(self):
        keys = list(THEMES)
        cur = self.core.db.get("theme")
        nxt = keys[(keys.index(cur) + 1) % len(keys)] if cur in keys else keys[0]
        self.core.db.set("theme", nxt)
        self.toast(f"Theme changed to {nxt}", "ok")
        self.rebuild(self.current)

    def open_data_folder(self):
        try:
            os.startfile(str(APPDIR))
        except Exception as e:
            self.toast(f"Could not open the data folder: {e}", "bad")

    # -- command palette
    def _palette_items(self):
        out = []
        for i, (key, name, icon, group) in enumerate(self.NAV):
            out.append((icon, name, f"{group.title()}  ·  Open workspace", f"Ctrl {i + 1}",
                        lambda k=key: self.show(k)))
        actions = [
            ("▶", "Play  ·  choose accounts and launch", "Launch workspace",
             "Ctrl 3", lambda: self.show("Play")),
            ("▦", "Arrange Roblox windows in a grid", "Window action",
             "", lambda: (self.core.arrange("grid"), self.toast("Windows arranged in a grid", "ok"))),
            ("▥", "Tile Roblox windows in a row", "Window action",
             "", lambda: (self.core.arrange("h"), self.toast("Windows tiled in a row", "ok"))),
            ("≣", "Open the activity log", "Go to the newest events",
             "", self._open_log),
            ("⌕", "Focus the account search", "Search from the top bar",
             "Ctrl F", self._focus_search),
            ("◐", "Switch to the next colour theme", "Appearance shortcut",
             "", self.cycle_theme),
            ("▤", "Toggle the compact sidebar", "Workspace layout",
             "Ctrl B", self.toggle_sidebar),
            ("↻", "Refresh the current workspace", "Reload live numbers",
             "F5", self.refresh_current),
            ("⚙", "Open appearance settings", "Themes, accent, density",
             "Ctrl 8", lambda: self.show("Settings")),
            ("⌂", "Open the RoManager data folder", "Database and logs",
             "", self.open_data_folder),
        ]
        out += actions
        q = self._pal_entry.get().strip().lower() if getattr(self, "_pal_entry", None) else ""
        if len(q) >= 2:
            rows = self.core.db.all("SELECT id, alias, username FROM accounts ORDER BY alias, username")
            for r in rows:
                name = r["alias"] or r["username"]
                if q in name.lower() or q in (r["username"] or "").lower():
                    out.append(("☺", name, f"Account  ·  @{r['username']}", "",
                                lambda n=name: self._search_account(n)))
        return out

    def _search_account(self, name):
        def apply(page):
            try:
                page.search.delete(0, "end")
                page.search.insert(0, name)
                page.rebuild()
            except Exception:
                pass
        self.show("Accounts", then=apply)

    def open_palette(self, _=None):
        if self._palette is not None:
            self.close_palette()
            return "break"
        self._close_pop()
        scrim = ctk.CTkFrame(self, fg_color=T["bg"], corner_radius=0)
        scrim.place(relx=0, rely=0, relwidth=1, relheight=1)
        scrim.lift()
        scrim.bind("<Button-1>", lambda e: self.close_palette())
        self._palette = scrim
        L(scrim, "◆", 300, color=blend(T["accent"], T["bg"], .055)).place(relx=.82, rely=.72, anchor="center")
        L(scrim, "R O   M A N A G E R   /   C O M M A N D", 8, True,
          color=blend(T["muted"], T["bg"], .35)).place(relx=.5, y=52, anchor="n")
        shadow = ctk.CTkFrame(scrim, fg_color=blend("#000000", T["bg"], .48), corner_radius=22,
                              width=674, height=470)
        shadow.place(relx=.5, y=76, anchor="n")
        card = ctk.CTkFrame(scrim, fg_color=T["panel"], border_color=blend(T["accent"], T["panel"], .52),
                            border_width=1, corner_radius=19, width=662)
        card.place(relx=.5, y=72, anchor="n")
        head = ctk.CTkFrame(card, fg_color="transparent")
        head.pack(fill="x", padx=16, pady=(14, 4))
        mark = ctk.CTkFrame(head, width=34, height=34, fg_color=T["accent"], corner_radius=10)
        mark.pack(side="left")
        mark.pack_propagate(False)
        ctk.CTkLabel(mark, text="◆", font=F(14, True), text_color="#FFFFFF").pack(expand=True)
        words = ctk.CTkFrame(head, fg_color="transparent")
        words.pack(side="left", padx=10)
        L(words, "COMMAND PALETTE", 9, True, color=T["lav"]).pack(anchor="w")
        L(words, "Jump to a workspace, run an action, or find an account.", 10, muted=True).pack(anchor="w")
        esc = ctk.CTkLabel(head, text="  ESC  ", font=F(8, True), text_color=T["muted"],
                           fg_color=T["panel2"], border_color=T["border"], border_width=1,
                           corner_radius=6, height=22)
        esc.pack(side="right")
        self._pal_entry = E(card, height=48, placeholder_text="⌕   Type a command, workspace or account…",
                            font=F(15), corner_radius=12)
        self._pal_entry.pack(fill="x", padx=16, pady=(8, 10))
        self._pal_entry.bind("<KeyRelease>", self._palette_filter)
        self._pal_entry.bind("<Down>", lambda e: self._pal_move(1))
        self._pal_entry.bind("<Up>", lambda e: self._pal_move(-1))
        self._pal_entry.bind("<Return>", lambda e: self._pal_run(None))
        hline(card, pady=0)
        self._pal_list = ctk.CTkScrollableFrame(
            card, fg_color="transparent", height=286, scrollbar_fg_color="transparent",
            scrollbar_button_color=blend(T["accent"], T["panel"], .22),
            scrollbar_button_hover_color=T["accent2"])
        self._pal_list.pack(fill="both", expand=True, padx=8, pady=(5, 2))
        foot = ctk.CTkFrame(card, fg_color="transparent")
        foot.pack(fill="x", padx=16, pady=(4, 13))
        L(foot, "↑ ↓  navigate      ↵  open      esc  close", 9, muted=True).pack(side="left")
        L(foot, "POWERED BY  R O M A N A G E R", 7, True,
          color=blend(T["muted"], T["panel"], .5)).pack(side="right")
        self._pal_sel = 0
        self._palette_render()
        try:
            card.update_idletasks()
            shadow.configure(height=card.winfo_reqheight() + 8)
        except Exception:
            pass
        self.after(35, self._pal_focus)

    def _pal_focus(self):
        try:
            self._pal_entry.focus_set()
        except Exception:
            pass

    def _palette_filter(self, _=None):
        self._pal_sel = 0
        self._palette_render()

    def _palette_render(self):
        if self._palette is None or not hasattr(self, "_pal_list"):
            return
        q = self._pal_entry.get().strip().lower()
        items = self._palette_items()
        if q:
            toks = q.split()
            items = [it for it in items if all(t in (it[1] + " " + it[2]).lower() for t in toks)]
        self._pal_items = items[:14]
        for w in self._pal_list.winfo_children():
            w.destroy()
        self._pal_rows = []
        if not self._pal_items:
            row = ctk.CTkFrame(self._pal_list, fg_color="transparent")
            row.pack(fill="x", pady=18)
            L(row, "No matching commands", 13, True).pack()
            L(row, "Try a workspace name, an action, or an account.", 10, muted=True).pack(pady=(2, 0))
            return
        self._pal_sel = max(0, min(getattr(self, "_pal_sel", 0), len(self._pal_items) - 1))
        for i, (icon, title, sub, hint, run) in enumerate(self._pal_items):
            on = i == self._pal_sel
            row = ctk.CTkFrame(self._pal_list, fg_color=T["accent_faint"] if on else "transparent",
                               corner_radius=10)
            row.pack(fill="x", padx=3, pady=1)
            bar = ctk.CTkFrame(row, width=2, fg_color=T["accent"] if on else "transparent", corner_radius=1)
            bar.pack(side="left", fill="y", padx=(2, 0), pady=7)
            glyph = ctk.CTkLabel(row, text=icon, width=30, height=30, corner_radius=9,
                                 fg_color=T["accent_soft"] if on else T["panel2"],
                                 text_color=T["lav"] if on else T["muted"], font=F(12, True))
            glyph.pack(side="left", padx=(9, 9), pady=7)
            words = ctk.CTkFrame(row, fg_color="transparent")
            words.pack(side="left", fill="x", expand=True, pady=5)
            L(words, title, 12, True, color=T["text"] if on else T["text"]).pack(anchor="w")
            L(words, sub, 9, muted=True).pack(anchor="w", pady=(0, 1))
            if hint:
                ctk.CTkLabel(row, text=f" {hint} ", font=F(8, True), text_color=T["muted"],
                             fg_color=T["panel2"], corner_radius=5, height=19).pack(side="right", padx=10)
            for w in (row, bar, glyph, words) + tuple(words.winfo_children()):
                w.bind("<Button-1>", lambda e, n=i: self._pal_run(n))
                w.configure(cursor="hand2")
                if not on:
                    w.bind("<Enter>", lambda e, r=row: self._pal_hover(r, True), add="+")
                    w.bind("<Leave>", lambda e, r=row: self._pal_hover(r, False), add="+")
            self._pal_rows.append(row)
        self._pal_scroll()

    def _pal_hover(self, row, on):
        try:
            if row not in self._pal_rows or self._pal_rows.index(row) == self._pal_sel:
                return
            row.configure(fg_color=blend(T["accent"], T["panel"], .05) if on else "transparent")
        except Exception:
            pass

    def _pal_move(self, delta):
        n = len(getattr(self, "_pal_items", []))
        if n:
            self._pal_sel = (self._pal_sel + delta) % n
            self._palette_render()
        return "break"

    def _pal_scroll(self):
        try:
            n = len(self._pal_items)
            canvas = self._pal_list._parent_canvas
            span = max(1, n - 5)
            top = max(0.0, min(1.0, (self._pal_sel - 2) / span))
            canvas.yview_moveto(top)
        except Exception:
            pass

    def _pal_run(self, idx=None):
        items = getattr(self, "_pal_items", [])
        if not items:
            return "break"
        i = self._pal_sel if idx is None else idx
        i = max(0, min(i, len(items) - 1))
        run = items[i][4]
        self.close_palette()
        self.after(10, run)
        return "break"

    def close_palette(self):
        pal, self._palette = self._palette, None
        self._pal_rows, self._pal_items = [], []
        if pal is not None:
            try:
                pal.destroy()
            except Exception:
                pass
        try:
            self.focus_set()
        except Exception:
            pass

